import { useEffect, useMemo, useState } from 'react';
import { Activity, ArrowLeftRight, ArrowUpRight, BookOpen, Boxes, BriefcaseBusiness, ChevronRight, CircleAlert, ClipboardCheck, Database, Download, FileJson, FileText, GitCompareArrows, Landmark, Layers3, LockKeyhole, Menu, Play, Plus, RefreshCw, Search, Shield, ShieldAlert, ShieldCheck, Trash2, Upload, WalletCards, X } from 'lucide-react';
import { assessmentSummary, newWorkspace, resolveSettlement, validateArchitecture, type ArchitectureConfig, type Finding, type Outcome, type Workspace } from './domain/architecture';
import { createLedgerState, executeLifecycle, type LedgerState, type LifecycleCommand } from './domain/lifecycle';
import { compareArchitectures, generateDecisionPack, matrixCsv, packMarkdown, systemOfRecordMatrix } from './domain/pack';
import { runScenario, scenarioCatalog, type ScenarioOutcome } from './domain/scenarios';
import { searchSources, sources } from './domain/research';
import { defaultUseCaseInputs, evaluateUseCase, frictionOptions, mechanismOptions, type Friction, type Readiness, type TokenisationMechanism, type UseCaseInputs } from './domain/use-case-decision';
import { appendScenarioRun, createStoredWorkspaces, deleteWorkspace, duplicateWorkspace, importWorkspace, loadStoredWorkspaces, persistStoredWorkspaces, upsertWorkspace, type StoredWorkspaces, type StoragePort } from './workbench/storage';
import { useSaaS } from './saas/context';

type Page='overview'|'decision'|'designer'|'assessment'|'lifecycle'|'scenarios'|'compare'|'research'|'money'|'dlt'|'custody'|'integration'|'regulation'|'about';
const pages:{id:Page;label:string;icon:typeof Boxes;group:string}[]=[
 {id:'overview',label:'Workbench overview',icon:Activity,group:'Design workspace'},
 {id:'decision',label:'Use-case decision',icon:BriefcaseBusiness,group:'Design workspace'},
 {id:'designer',label:'Architecture designer',icon:Boxes,group:'Design workspace'},
 {id:'assessment',label:'Architecture assessment',icon:ClipboardCheck,group:'Engineering'},
 {id:'lifecycle',label:'Lifecycle simulator',icon:ArrowLeftRight,group:'Engineering'},
 {id:'scenarios',label:'Scenario laboratory',icon:ShieldAlert,group:'Engineering'},
 {id:'compare',label:'Compare & design pack',icon:GitCompareArrows,group:'Engineering'},
 {id:'money',label:'Digital money research',icon:WalletCards,group:'Research library'},
 {id:'dlt',label:'DLT platform research',icon:Layers3,group:'Research library'},
 {id:'custody',label:'Institutional custody',icon:LockKeyhole,group:'Research library'},
 {id:'integration',label:'Integration architecture',icon:Database,group:'Research library'},
 {id:'regulation',label:'Regulation & standards',icon:Landmark,group:'Research library'},
 {id:'research',label:'Research & sources',icon:BookOpen,group:'Research library'},
 {id:'about',label:'About this workbench',icon:BriefcaseBusiness,group:'Project'}
];
const pageTitles:Record<Page,string>={overview:'Design workspace',decision:'Use-case decision',designer:'Architecture designer',assessment:'Architecture assessment',lifecycle:'Lifecycle simulator',scenarios:'Scenario laboratory',compare:'Compare & design pack',research:'Research & sources',money:'Digital money research',dlt:'DLT platform research',custody:'Institutional custody',integration:'Integration architecture',regulation:'Regulation & standards',about:'About this workbench'};
const groups=['Design workspace','Engineering','Research library','Project'];
const pretty=(v:string)=>v.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const fmtMinor=(minor:number,currency:string)=>new Intl.NumberFormat('en-GB',{style:'currency',currency,maximumFractionDigits:2}).format(minor/100);
function loadInitial(storage:StoragePort):StoredWorkspaces{try{return loadStoredWorkspaces(storage);}catch{return createStoredWorkspaces();}}
function tenantStorage(scope:string):StoragePort{const prefix='ita-tenant:'+scope+':';return {getItem:key=>window.localStorage.getItem(prefix+key),setItem:(key,value)=>window.localStorage.setItem(prefix+key,value)};}

export default function App(){
 const saas=useSaaS();
 const storage=useMemo(()=>saas.enabled&&saas.organization&&saas.session?tenantStorage(saas.organization.id+':'+saas.session.user.id):window.localStorage,[saas.enabled,saas.organization?.id,saas.session?.user.id]);
 const [store,setStore]=useState<StoredWorkspaces>(()=>loadInitial(storage));
 const [page,setPage]=useState<Page>(()=>{const hash=window.location.hash.slice(1) as Page;return pages.some(p=>p.id===hash)?hash:'overview';});
 const [mobileNav,setMobileNav]=useState(false),[notice,setNotice]=useState(''),[query,setQuery]=useState(''),[sourceCategory,setSourceCategory]=useState('All');
 const [scenarioId,setScenarioId]=useState('baseline'),[lastScenario,setLastScenario]=useState<ScenarioOutcome|null>(null),[compareLeft,setCompareLeft]=useState(''),[compareRight,setCompareRight]=useState('');
 const [ledger,setLedger]=useState<LedgerState>(()=>createLedgerState()),[lifecycleNotice,setLifecycleNotice]=useState('Prepare the sandbox or run individual domain commands.');
 const workspace=store.workspaces.find(w=>w.id===store.activeId)||store.workspaces[0];
 const config=workspace.config,findings=useMemo(()=>validateArchitecture(config),[config]),summary=assessmentSummary(findings),matrix=useMemo(()=>systemOfRecordMatrix(config),[config]);
 useEffect(()=>{try{persistStoredWorkspaces(storage,store);}catch{console.warn('Browser storage is unavailable; export the workspace to keep a local copy.');}},[storage,store]);
 useEffect(()=>{const onHash=()=>{const hash=window.location.hash.slice(1) as Page;if(pages.some(p=>p.id===hash))setPage(hash);};window.addEventListener('hashchange',onHash);return()=>window.removeEventListener('hashchange',onHash);},[]);
 useEffect(()=>{document.title=`${pageTitles[page]} | Institutional Tokenisation Architecture`;const desc=document.querySelector('meta[name="description"]');desc?.setAttribute('content',`Institutional financial infrastructure workbench: ${pageTitles[page].toLowerCase()} for tokenised securities, money, custody and settlement.`);let canonical=document.querySelector<HTMLLinkElement>('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical);}canonical.href=`https://institutional-tokenisation-architec.vercel.app/#${page}`;},[page]);
 const navigate=(id:Page)=>{setPage(id);window.history.pushState(null,'',`#${id}`);setMobileNav(false);};
 const updateConfig=(key:keyof ArchitectureConfig,value:ArchitectureConfig[keyof ArchitectureConfig])=>{const updated={...workspace,config:{...config,[key]:value},updatedAt:new Date().toISOString()};setStore(s=>upsertWorkspace(s,updated,false));};
 const updateWorkspace=(patch:Partial<Workspace>)=>setStore(s=>upsertWorkspace(s,{...workspace,...patch,updatedAt:new Date().toISOString()},false));
 const setActive=(id:string)=>{setStore(s=>({...s,activeId:id}));setLedger(createLedgerState());setLastScenario(null);};
 const notify=(message:string)=>{setNotice(message);window.setTimeout(()=>setNotice(''),5000);};
 const doImport=async(file?:File)=>{if(!file)return;try{const value=JSON.parse(await file.text());setStore(s=>importWorkspace(s,value));notify('Architecture workspace imported and activated.');}catch(e){notify(`Import failed: ${e instanceof Error?e.message:'Invalid file'}`);}};
 const exportWorkspace=()=>download(`${fileName(workspace.name)}.json`,JSON.stringify(workspace,null,2),'application/json');
 const duplicate=()=>{try{const next=duplicateWorkspace(store,workspace.id);setStore(next);notify('Workspace duplicated.');}catch(e){notify(String(e));}};
 const deleteActive=()=>{if(store.workspaces.length<2){notify('Keep at least one workspace.');return;}setStore(s=>deleteWorkspace(s,workspace.id));setLedger(createLedgerState());};
 const runOneScenario=(id=scenarioId)=>{const result=runScenario(config,id);setLastScenario(result);setStore(s=>appendScenarioRun(s,result));return result;};
 const runCommand=(cmd:LifecycleCommand)=>{try{const next=executeLifecycle(ledger,config,cmd);setLedger(next);setLifecycleNotice(next.events[next.events.length-1]?.detail||'Command completed.');}catch(e){setLifecycleNotice(e instanceof Error?e.message:'Command rejected. No state changes applied.');}};
 const prepareLifecycle=()=>{try{let next=createLedgerState();const units=Math.min(100,config.issueSizeUnits);const cmds:LifecycleCommand[]=[{type:'authorize-issuance'},{type:'issue',units},{type:'onboard',investor:'ALICE',eligible:true},{type:'onboard',investor:'BOB',eligible:true},{type:'fund',account:'ALICE',amountMinor:10_000_000},{type:'fund',account:'BOB',amountMinor:10_000_000},{type:'subscribe',investor:'ALICE',units:Math.floor(units/2),amountMinor:Math.floor(units/2)*config.faceValueMinor,instructionId:`SUB-${workspace.id}`}];for(const cmd of cmds)next=executeLifecycle(next,config,cmd);setLedger(next);setLifecycleNotice('Synthetic issue authorized, minted, allocated and funded. Values are integer minor units.');}catch(e){setLifecycleNotice(e instanceof Error?e.message:'Preparation failed.');}};
 const pack=useMemo(()=>generateDecisionPack(workspace,findings),[workspace,findings]);
 const exportPack=()=>download(`${fileName(workspace.name)}-decision-pack.json`,JSON.stringify(pack,null,2),'application/json');
 const exportMarkdown=()=>download(`${fileName(workspace.name)}-decision-pack.md`,packMarkdown(pack),'text/markdown');
 const exportCsv=()=>download(`${fileName(workspace.name)}-system-of-record.csv`,matrixCsv(matrix),'text/csv');
 const left=store.workspaces.find(w=>w.id===compareLeft),right=store.workspaces.find(w=>w.id===compareRight);const differences=left&&right?compareArchitectures(left,right):[];
 const sourceResults=searchSources(query,sourceCategory);
 const runHistory=store.runs;

 return <div className="platform">
  <aside className={`side-panel ${mobileNav?'mobile-open':''}`}>
   <div className="platform-brand"><div className="platform-mark"><Landmark size={18}/></div><div><b>ITA WORKBENCH</b><small>INSTITUTIONAL DESIGN ENVIRONMENT</small></div><button className="mobile-close" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><X size={17}/></button></div>
   <div className="workspace-picker"><label htmlFor="workspace-select">ACTIVE WORKSPACE</label><select id="workspace-select" value={workspace.id} onChange={e=>setActive(e.target.value)}>{store.workspaces.map(w=><option value={w.id} key={w.id}>{w.name}</option>)}</select></div>
   <nav aria-label="Workbench navigation">{groups.map(group=><section className="nav-group" key={group}><div className="nav-group-title">{group}</div>{pages.filter(p=>p.group===group).map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>navigate(item.id)} className={`platform-nav ${page===item.id?'selected':''}`} aria-current={page===item.id?'page':undefined}><Icon size={15}/><span>{item.label}</span></button>;})}</section>)}</nav>
   <div className="side-health"><span className="health-dot"/> LOCAL SYNTHETIC WORKSPACE <small>Browser storage · No connected systems</small></div>
  </aside>
  {mobileNav&&<button className="nav-scrim" aria-label="Close menu" onClick={()=>setMobileNav(false)}/>}
  <main className="platform-main">
   <header className="platform-header"><div className="header-left"><button className="mobile-menu" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={18}/></button><div className="breadcrumbs"><span>Institutional Tokenisation Architecture</span><ChevronRight size={13}/><b>{pageTitles[page]}</b></div></div><div className="header-context"><span className="live-indicator"/> Versioned local design <span className="header-divider"/> <a href="https://github.com/vishnugovind10/institutional-tokenisation-architecture" target="_blank" rel="noreferrer">Repository <ArrowUpRight size={12}/></a></div></header>
   {notice&&<div role="status" className="toast-notice">{notice}<button aria-label="Dismiss notice" onClick={()=>setNotice('')}><X size={14}/></button></div>}
   <div className="platform-content">
    {page==='overview'&&<Overview workspace={workspace} config={config} findings={findings} summary={summary} matrix={matrix} runHistory={runHistory} navigate={navigate} onExport={exportWorkspace} onNew={()=>{const next=newWorkspace(`Architecture ${store.workspaces.length+1}`);setStore(s=>upsertWorkspace(s,next,true));setLedger(createLedgerState());}}/>}
    {page==='decision'&&<UseCaseDecision/>}
    {page==='designer'&&<Designer workspace={workspace} config={config} update={updateConfig} uUpdate={name=>updateWorkspace({name})} onDuplicate={duplicate} onDelete={deleteActive} onExport={exportWorkspace} onImport={doImport}/>}
    {page==='assessment'&&<Assessment findings={findings} summary={summary} config={config}/>}
    {page==='lifecycle'&&<Lifecycle config={config} ledger={ledger} notice={lifecycleNotice} onCommand={runCommand} onPrepare={prepareLifecycle}/>}
    {page==='scenarios'&&<ScenarioLab config={config} scenarioId={scenarioId} setScenarioId={setScenarioId} lastScenario={lastScenario} run={runOneScenario} history={runHistory}/>}
    {page==='compare'&&<ComparePack workspaces={store.workspaces} left={compareLeft} right={compareRight} setLeft={setCompareLeft} setRight={setCompareRight} differences={differences} pack={pack} onJson={exportPack} onMarkdown={exportMarkdown} onCsv={exportCsv}/>}
    {page==='research'&&<ResearchPage query={query} setQuery={setQuery} category={sourceCategory} setCategory={setSourceCategory} results={sourceResults}/>}
    {page==='money'&&<MoneyPage config={config} update={updateConfig}/>}
    {page==='dlt'&&<DltPage config={config} update={updateConfig}/>}
    {page==='custody'&&<CustodyPage config={config} update={updateConfig}/>}
    {page==='integration'&&<IntegrationPage config={config} update={updateConfig}/>}
    {page==='regulation'&&<RegulationPage query={query} setQuery={setQuery} category={sourceCategory} setCategory={setSourceCategory} results={sourceResults} jurisdiction={config.jurisdiction} update={updateConfig}/>}
    {page==='about'&&<AboutPage/>}
    <footer className="platform-footer"><span>ITA WORKBENCH · SCHEMA {workspace.schemaVersion} · {workspace.name}</span><span>Deterministic synthetic design aid · Not a production financial system</span></footer>
   </div>
  </main>
 </div>;
}

function Overview({workspace,config,findings,summary,matrix,runHistory,navigate,onExport,onNew}:{workspace:Workspace;config:ArchitectureConfig;findings:Finding[];summary:ReturnType<typeof assessmentSummary>;matrix:ReturnType<typeof systemOfRecordMatrix>;runHistory:ScenarioOutcome[];navigate:(p:Page)=>void;onExport:()=>void;onNew:()=>void}){
 const unresolved=findings.filter(f=>f.status==='FAIL'||f.status==='WARNING'||f.status==='UNASSESSED');
 return <><div className="page-heading"><div><div className="eyebrow">ACTIVE ARCHITECTURE WORKSPACE</div><h1>{workspace.name}</h1><p>Configure financial asset, digital money, custody and settlement boundaries. Assess design consistency and execute deterministic lifecycle scenarios.</p></div><div className="heading-actions"><button className="btn secondary" onClick={onExport}><FileJson size={14}/> Export workspace</button><button className="btn primary" onClick={onNew}><Plus size={15}/> New design</button></div></div>
  <div className="overview-config-strip"><span><b>{config.instrument}</b><small>Asset</small></span><i/><span><b>{pretty(config.money)}{config.money==='deposit'?` · ${pretty(config.depositModel)}`:''}</b><small>Money architecture</small></span><i/><span><b>{config.dlt} · {pretty(config.topology)}</b><small>Ledger architecture</small></span><i/><span><b>{pretty(config.custody)}</b><small>Custody model</small></span><i/><span><b>{pretty(resolveSettlement(config).effective)}</b><small>Effective settlement</small></span></div>
  <div className="dashboard-grid"><section className="panel validation-panel"><div className="panel-head"><div><div className="eyebrow">DESIGN ASSESSMENT</div><h2>Control findings</h2></div><button className="text-link" onClick={()=>navigate('assessment')}>Open assessment <ChevronRight size={14}/></button></div><div className="finding-counts"><Count status="PASS" count={summary.pass}/><Count status="WARNING" count={summary.warning}/><Count status="FAIL" count={summary.fail}/><Count status="UNASSESSED" count={summary.unassessed}/></div><div className="decision-list">{unresolved.slice(0,4).map(f=><div className="decision-row" key={f.id}><StatusPill status={f.status}/><span><b>{f.id}</b> {f.description}</span><small>{f.domain}</small></div>)}</div></section>
   <section className="panel quick-panel"><div className="eyebrow">ENGINEERING MODULES</div><h2>Continue design work</h2><div className="quick-links"><QuickLink icon={BriefcaseBusiness} title="Evaluate a tokenisation use case" sub="Test business need, prerequisites and pilot scope" go={()=>navigate('decision')}/><QuickLink icon={Boxes} title="Configure architecture" sub="Business, money, DLT and controls" go={()=>navigate('designer')}/><QuickLink icon={ArrowLeftRight} title="Execute lifecycle" sub="Issue, subscribe, settle and redeem" go={()=>navigate('lifecycle')}/><QuickLink icon={ShieldAlert} title="Inject a failure" sub="Run 14 reproducible scenarios" go={()=>navigate('scenarios')}/><QuickLink icon={FileText} title="Generate design pack" sub="JSON, Markdown and CSV outputs" go={()=>navigate('compare')}/></div></section>
   <section className="panel matrix-panel"><div className="panel-head"><div><div className="eyebrow">SYSTEM-OF-RECORD MATRIX</div><h2>Authority and operational records</h2></div></div><div className="table-wrap"><table><thead><tr><th>Domain</th><th>Record / responsibility</th><th>Role</th></tr></thead><tbody>{matrix.map(row=><tr key={row.domain}><td>{row.domain}</td><td><b>{row.record}</b><small>{row.responsibility}</small></td><td>{row.role}</td></tr>)}</tbody></table></div></section>
   <section className="panel recent-panel"><div className="panel-head"><div><div className="eyebrow">RECENT SCENARIO ACTIVITY</div><h2>Execution history</h2></div><button className="text-link" onClick={()=>navigate('scenarios')}>Scenario lab <ChevronRight size={14}/></button></div>{runHistory.length?runHistory.slice(-4).reverse().map((run,i)=><div className="recent-row" key={`${run.id}-${i}`}><StatusPill status={run.status}/><span><b>{run.name}</b><small>{run.settlementStatus}</small></span><time>{run.id}</time></div>):<p className="empty-state">No scenarios have been run in this browser workspace.</p>}</section>
  </div><div className="method-note"><ShieldCheck size={15}/><span>The assessment reports individual rules without a composite score. “Legal finality” remains unassessed unless the design owner records external legal and scheme-rule review.</span></div>
 </>;
}
function Count({status,count}:{status:Outcome;count:number}){return <div className={`count-card ${status.toLowerCase().replace(' ','-')}`}><span>{status}</span><b>{count}</b></div>}
function QuickLink({icon:Icon,title,sub,go}:{icon:typeof Boxes;title:string;sub:string;go:()=>void}){return <button className="quick-link" onClick={go}><Icon size={16}/><span><b>{title}</b><small>{sub}</small></span><ChevronRight size={14}/></button>}
function StatusPill({status}:{status:Outcome|string}){return <span className={`status-pill ${status.toLowerCase().replace(/\s/g,'-')}`}>{status}</span>}
function SectionTitle({eyebrow,title,copy,actions}:{eyebrow:string;title:string;copy?:string;actions?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{copy&&<p>{copy}</p>}</div>{actions&&<div className="heading-actions">{actions}</div>}</div>}
function Field({label,value,onChange,options,help}:{label:string;value:string|number;onChange:(v:string)=>void;options?:string[];help?:string}){return <label className="form-field"><span>{label}</span>{options?<select value={String(value)} onChange={e=>onChange(e.target.value)}>{options.map(x=><option key={x} value={x}>{x}</option>)}</select>:<input value={value} onChange={e=>onChange(e.target.value)} />}{help&&<small>{help}</small>}</label>}
function Toggle({label,checked,onChange,help}:{label:string;checked:boolean;onChange:(v:boolean)=>void;help?:string}){return <label className="toggle-field"><span><b>{label}</b>{help&&<small>{help}</small>}</span><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><i/></label>}
function Panel({title,copy,children}:{title:string;copy?:string;children:React.ReactNode}){return <section className="panel form-panel"><div className="panel-head"><div><h2>{title}</h2>{copy&&<p>{copy}</p>}</div></div>{children}</section>}

function Designer({workspace,config:c,update,uUpdate,onDuplicate,onDelete,onExport,onImport}:{workspace:Workspace;config:ArchitectureConfig;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void;uUpdate:(name:string)=>void;onDuplicate:()=>void;onDelete:()=>void;onExport:()=>void;onImport:(f?:File)=>void}){
 const val=(key:keyof ArchitectureConfig)=>String(c[key]);const field=(key:keyof ArchitectureConfig,label:string,options:string[],help?:string)=><Field key={key} label={label} value={val(key)} options={options} help={help} onChange={v=>update(key,v as ArchitectureConfig[keyof ArchitectureConfig])}/>;
 const number=(key:'issueSizeUnits'|'faceValueMinor'|'couponBps'|'mpcAvailableSigners'|'mpcThreshold',label:string,help?:string)=><Field key={key} label={label} value={c[key]} help={help} onChange={v=>update(key,Math.max(0,Math.floor(Number(v)||0)))}/>;
 const toggle=(key:keyof ArchitectureConfig,label:string,help?:string)=><Toggle key={key} label={label} checked={Boolean(c[key])} help={help} onChange={v=>update(key,v)}/>;
 const investorCategories=(value:string)=>{const next=value.split(',').map(x=>x.trim()).filter(Boolean);update('investorCategories',next);};
 return <><SectionTitle eyebrow="VERSIONED ARCHITECTURE CONFIGURATION" title="Architecture designer" copy="Every field feeds deterministic design rules, modeled operating behavior or pack outputs. Workspaces are saved locally in this browser." actions={<><button className="btn secondary" onClick={onExport}><Download size={14}/> Export JSON</button><button className="btn secondary" onClick={()=>{const input=document.querySelector<HTMLInputElement>('#workspace-import');input?.click();}}><Upload size={14}/> Import JSON</button><input id="workspace-import" type="file" accept="application/json,.json" hidden onChange={e=>onImport(e.target.files?.[0])}/></>}/>
  <div className="designer-toolbar"><label className="workspace-name">Workspace name<input value={workspace.name} onChange={e=>uUpdate(e.target.value)}/></label><div className="heading-actions"><button className="btn secondary" onClick={onDuplicate}><Plus size={14}/> Duplicate</button><button className="btn danger-quiet" onClick={onDelete}><Trash2 size={14}/> Delete</button></div><span className="save-indicator"><span className="health-dot"/> Autosaved locally</span></div>
  <div className="designer-grid"><div className="designer-column">
  <Panel title="Business and asset model" copy="Instrument authority, rights and issuance parameters."><div className="form-grid">{field('issuerType','Issuer type',['Bank','Corporate issuer','Fund'])}{field('instrument','Financial instrument',['Bond','Fund units'])}{field('assetClass','Asset class',['Debt security','Fund unit'])}{field('currency','Instrument currency',['EUR','USD','GBP'])}{field('jurisdiction','Jurisdiction',['European Union','United Kingdom','United States','Other'])}{field('legalRegister','Legal register model',['Transfer-agent register','Issuer register','CSD register','On-chain register','Unassigned'])}{field('transferAgent','Transfer-agent responsibility',['Issuer-appointed transfer agent','Issuer operations','Fund administrator','Unassigned'])}{field('issuanceAuthority','Issuance authority',['Issuer governance committee','Board / delegated committee','Unassigned'])}{number('issueSizeUnits','Authorized issue units')}{number('faceValueMinor','Face value per unit (minor units)')}{<label className="form-field" key="maturityDate"><span>Maturity date</span><input type="date" value={c.maturityDate} onChange={e=>update('maturityDate',e.target.value)}/></label>}{number('couponBps','Annual coupon (basis points)')}</div><label className="form-field full-field"><span>Investor categories · comma separated</span><input value={c.investorCategories.join(', ')} onChange={e=>investorCategories(e.target.value)}/></label><Toggle label="Restrict transfers to eligible investor categories" checked={c.transferRestrictions} onChange={v=>update('transferRestrictions',v)}/></Panel>
   <Panel title="Digital money and deposit model" copy="The bank deposit mirror and omnibus pool use different books and coverage rules."><div className="form-grid">{field('money','Cash instrument',['deposit','cbdc','stablecoin','existing-rails'])}{field('depositModel','Deposit architecture',['mirror','omnibus'])}{field('redemptionOwner','Redemption owner',['Issuer treasury','Deposit bank operations','Token issuer operations','Unassigned'])}{field('liquidityOwner','Liquidity owner',['Issuer treasury','Bank treasury','Custodian','Unassigned'])}</div>{c.money==='deposit'&&c.depositModel==='mirror'?<div className="toggle-grid">{toggle('coreBankAuthority','Core banking remains authoritative')}{toggle('mirrorSynchronization','Deposit mirror synchronization is controlled')}{toggle('moneyReconciliation','Core bank and token ledger reconcile')}</div>:c.money==='deposit'?<div className="toggle-grid">{toggle('omnibusBackingDefined','Pooled backing account is defined')}{toggle('entitlementModel','Investor entitlement subledger is defined')}{toggle('moneyReconciliation','Backing and token liabilities reconcile')}</div>:<div className="inline-callout">Non-deposit cash model selected. Deposit-specific accounting tests are unassessed; scheme, issuer liability, redemption and settlement assets need a separate review.</div>}</Panel>
   <Panel title="Custody and signing controls" copy="HSM availability and MPC signer threshold are evaluated independently."><div className="form-grid">{field('custody','Custody architecture',['hsm','mpc','hybrid','third-party'])}{number('mpcAvailableSigners','Available MPC signers')}{number('mpcThreshold','MPC signing threshold')}</div><div className="toggle-grid">{toggle('custodyPolicy','Delegated transaction policy is present')}{toggle('makerChecker','Maker-checker separation is present')}{toggle('keyRecovery','Key recovery and continuity defined')}{c.custody!=='mpc'&&toggle('hsmAvailable','HSM signing service is available')}</div><small className="muted-note">Authorization outcomes are simulated; no cryptographic key, HSM or MPC protocol is implemented.</small></Panel>
  </div><div className="designer-column">
   <Panel title="DLT, topology and settlement" copy="Requested atomicity is downgraded unless system boundaries model one shared domain."><div className="form-grid">{field('dlt','DLT profile',['Hyperledger Besu','Hyperledger Fabric','Canton','Ethereum','Quorum','Stellar','Avalanche','Hedera'])}{field('topology','Network topology',['single-ledger','multiple-ledgers','shared-coordination','existing-systems'])}{field('settlement','Settlement architecture',['atomic','coordinated','payment-rails','escrow'])}{field('settlementDomain','Settlement domain',['shared','separate'])}{field('cashMechanism','Cash-leg mechanism',['same-ledger','linked-ledger','offchain-rail'])}</div><div className="effective-model"><div className="eyebrow">EFFECTIVE SETTLEMENT MODEL</div><b>{pretty(resolveSettlement(c).effective)}</b><p>{resolveSettlement(c).reason}</p></div></Panel>
   <Panel title="Integration and assurance controls" copy="Each selection changes validation and the generated design pack."><div className="toggle-grid">{toggle('canonicalIds','Canonical transaction identifiers')}{toggle('idempotency','Idempotency and replay protection')}{toggle('timeoutAndRecovery','Timeout and recovery procedures')}{toggle('independentObservers','Independent status observations')}{toggle('visibilityBoundary','Participant data-visibility boundary')}{toggle('legalFinalityAssessment','External legal-finality assessment completed')}{toggle('iso20022Mapping','Conceptual ISO 20022 mapping selected')}</div></Panel>
   <Panel title="Architecture boundary" copy="In-scope options are design assumptions only. No banking, payment, custody or DLT integration is connected."><div className="boundary-list"><span><Database size={14}/> System adapters <b>Documented interfaces</b></span><span><LockKeyhole size={14}/> Key management <b>Simulated policy</b></span><span><ArrowLeftRight size={14}/> Settlement fabric <b>Deterministic local engine</b></span><span><FileText size={14}/> Evidence <b>Local synthetic references</b></span></div></Panel>
   <button className="btn secondary" onClick={onDuplicate}><Plus size={14}/> Save as separate design</button>
  </div></div></>;
}

function Assessment({findings,summary,config}:{findings:Finding[];summary:ReturnType<typeof assessmentSummary>;config:ArchitectureConfig}){
 const [filter,setFilter]=useState('All');const visible=findings.filter(f=>filter==='All'||f.status===filter);const effective=resolveSettlement(config);
 return <><SectionTitle eyebrow="DETERMINISTIC DESIGN RULES · NO COMPOSITE SCORE" title="Architecture assessment" copy="Each finding identifies its control, evidence, impact, owner and remediation. Results update from the active architecture configuration." actions={<select aria-label="Filter assessment findings" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option>{(['PASS','WARNING','FAIL','UNASSESSED','NOT APPLICABLE'] as Outcome[]).map(s=><option key={s}>{s}</option>)}</select>}/>
  <div className="assessment-intro"><div className="effective-model"><span className="eyebrow">SETTLEMENT MODEL RESOLUTION</span><b>{pretty(effective.effective)} execution</b><p>{effective.reason}</p></div><div className="finding-counts"><Count status="PASS" count={summary.pass}/><Count status="WARNING" count={summary.warning}/><Count status="FAIL" count={summary.fail}/><Count status="UNASSESSED" count={summary.unassessed}/></div></div>
  <div className="assessment-table">{visible.map(f=><article className={`finding-card ${f.status.toLowerCase()}`} key={f.id}><div className="finding-main"><div className="finding-label"><StatusPill status={f.status}/><code>{f.id}</code><span>{f.domain}</span></div><h3>{f.description}</h3><p>{f.finding}</p></div><div className="finding-grid"><div><b>Impact</b><p>{f.impact}</p></div><div><b>Configuration evidence</b><code>{f.evidence}</code></div><div><b>Remediation · owner: {f.domain}</b><p>{f.remediation}</p></div></div></article>)}</div>
  <div className="method-note"><CircleAlert size={15}/><span>PASS means the selected design inputs satisfy this local rule. It does not mean the architecture is secure, compliant, production ready or legally final.</span></div>
 </>;
}

function Lifecycle({config:c,ledger,notice,onCommand,onPrepare}:{config:ArchitectureConfig;ledger:LedgerState;notice:string;onCommand:(c:LifecycleCommand)=>void;onPrepare:()=>void}){
 const [units,setUnits]=useState(10),[cash,setCash]=useState(1_000_000),[instruction,setInstruction]=useState('DVP-USER-001');
 const minted=ledger.registerIssuedUnits,hasInvestor=ledger.eligibleInvestors.includes('ALICE');
 return <><SectionTitle eyebrow="DETERMINISTIC FINANCIAL DOMAIN ENGINE" title="Lifecycle simulator" copy="Execute state-changing commands across legal-register supply, token positions, bank cash, token cash, custody authorization and reconciliation." actions={<button className="btn secondary" onClick={onPrepare}><Play size={14}/> Prepare synthetic issue</button>}/>
  <div className="ledger-metrics"><Metric label="Authorized supply" value={`${c.issueSizeUnits.toLocaleString()} units`}/><Metric label="Legal register" value={`${ledger.registerIssuedUnits.toLocaleString()} units issued`}/><Metric label="Token supply" value={`${Object.values(ledger.assetBalances).reduce((a,b)=>a+b,0).toLocaleString()} units tracked`}/><Metric label="Money model" value={`${pretty(c.money)} · ${pretty(c.depositModel)}`}/></div>
  <div className="lifecycle-grid"><div className="lifecycle-commands"><Panel title="Instrument authorization and issuance" copy="Issue supply is checked against the configured authorized quantity."><div className="command-row"><button className="btn secondary" onClick={()=>onCommand({type:'authorize-issuance'})}>Authorize issue</button><button className="btn secondary" disabled={!ledger.issuanceAuthorized||minted>=c.issueSizeUnits} onClick={()=>onCommand({type:'issue',units:Math.min(100,c.issueSizeUnits-minted)})}>Mint up to 100 units</button></div><div className="command-row"><button className="btn secondary" onClick={()=>onCommand({type:'onboard',investor:'ALICE',eligible:true})}>Onboard Alice</button><button className="btn secondary" onClick={()=>onCommand({type:'onboard',investor:'BOB',eligible:true})}>Onboard Bob</button></div></Panel>
    <Panel title="Funding and primary subscription" copy="Amounts use integer minor units. Deposit mirror and omnibus backing are booked separately."><div className="command-row"><button className="btn secondary" onClick={()=>onCommand({type:'fund',account:'ALICE',amountMinor:10_000_000})}>Fund Alice · €100k</button><button className="btn secondary" onClick={()=>onCommand({type:'fund',account:'BOB',amountMinor:10_000_000})}>Fund Bob · €100k</button></div><div className="command-row"><button className="btn secondary" disabled={!hasInvestor} onClick={()=>onCommand({type:'subscribe',investor:'ALICE',units:Math.min(20,ledger.assetBalances.ISSUER||0),amountMinor:Math.min(20,ledger.assetBalances.ISSUER||0)*c.faceValueMinor,instructionId:`SUB-${Date.now()}`})}>Subscribe up to 20 units</button><span className="muted-note">Requires minted inventory, Alice eligibility and cash.</span></div></Panel>
    <Panel title="Secondary trade · delivery versus payment" copy="Custody availability and cash sufficiency are verified before either balance is mutated."><div className="form-grid three"><Field label="Units" value={units} onChange={v=>setUnits(Math.max(1,Number(v)||1))}/><Field label="Cash amount · minor units" value={cash} onChange={v=>setCash(Math.max(1,Number(v)||1))}/><Field label="Canonical instruction ID" value={instruction} onChange={setInstruction}/></div><div className="command-row"><button className="btn primary" onClick={()=>onCommand({type:'dvp',buyer:'BOB',seller:'ALICE',units,amountMinor:cash,instructionId:instruction,custodyAuthorized:true})}><ArrowLeftRight size={14}/> Submit DvP instruction</button><span className="small-note">Configured settlement: {pretty(resolveSettlement(c).effective)}. Legal finality is never inferred.</span></div></Panel>
    <Panel title="Servicing, redemption and reconciliation" copy="Coupon payments and maturity redemption use the current configured instrument terms."><div className="command-row"><button className="btn secondary" onClick={()=>onCommand({type:'coupon',issuer:'ISSUER',asOfDate:'2027-05-20',paymentsPerYear:2})}>Process coupon</button><button className="btn secondary" onClick={()=>onCommand({type:'redeem',investor:'ALICE',units:Math.min(1,ledger.assetBalances.ALICE||0),amountMinor:c.faceValueMinor,asOfDate:c.maturityDate,custodyAuthorized:true})}>Redeem at maturity</button><button className="btn secondary" onClick={()=>onCommand({type:'reconcile'})}>Reconcile records</button><button className="btn danger-quiet" onClick={()=>{onCommand({type:'inject-divergence',ledger:'asset',account:'UNEXPLAINED',amount:1});}}>Inject unexplained asset</button></div></Panel>
   </div><aside className="panel ledger-panel"><div className="eyebrow">INDEPENDENT FINANCIAL RECORDS</div><h2>Current domain state</h2><StateBlock title="Legal asset register" value={`${ledger.registerIssuedUnits} units issued`} detail={`Authorized ${c.issueSizeUnits}; asset authority ${c.legalRegister}`}/><StateBlock title="Tokenized asset ledger" value={Object.entries(ledger.assetBalances).filter(([,n])=>n!==0).map(([a,n])=>`${a} ${n}`).join(' · ')||'No positions'} detail="Token state is an operational representation."/><StateBlock title={c.money==='deposit'&&c.depositModel==='omnibus'?'Omnibus backing account':'Core bank deposit account'} value={Object.entries(ledger.bankCashMinor).map(([a,n])=>`${a} ${fmtMinor(n,c.currency)}`).join(' · ')||'No bank-account balance'} detail={c.money==='deposit'&&c.depositModel==='mirror'?'Underlying deposit authority remains with core banking.':c.money==='deposit'?'Pooled bank asset is separate from investor token entitlements.':'Not the selected cash instrument ledger.'}/><StateBlock title={c.money==='deposit'?'Tokenized deposit ledger':`${pretty(c.money)} cash ledger`} value={c.money==='deposit'?Object.entries(ledger.tokenCashMinor).map(([a,n])=>`${a} ${fmtMinor(n,c.currency)}`).join(' · ')||'No token balances':Object.entries(ledger.cashInstrumentMinor).map(([a,n])=>`${a} ${fmtMinor(n,c.currency)}`).join(' · ')||'No selected-instrument balances'} detail={c.money==='deposit'&&c.depositModel==='omnibus'?`Aggregate entitlements; pooled backing ${fmtMinor(ledger.omnibusBackingMinor,c.currency)}.`:c.money==='deposit'?'Mirror positions reconcile account by account.':'This cash position is not represented as a bank deposit.'}/><div className={`lifecycle-notice ${notice.includes('Insufficient')||notice.includes('unavailable')||notice.includes('exception')?'error':''}`} role="status">{notice}</div>
   <div className="timeline-head"><h3>Domain event history</h3><span>{ledger.events.length} events</span></div><div className="event-list">{ledger.events.length?ledger.events.slice().reverse().map(e=><div className="domain-event" key={e.id}><div><b>{pretty(e.type)}</b><time>{e.at}</time></div><p>{e.detail}</p><code>{e.evidence}</code><StatusPill status={e.status}/></div>):<p className="empty-state">No lifecycle commands have been applied.</p>}</div>
   <div className="method-note compact"><Shield size={14}/><span>Sandbox execution only. Event references are synthetic and unsigned.</span></div>
  </aside></div></>;
}
function Metric({label,value}:{label:string;value:string}){return <div className="metric-card"><span>{label}</span><b>{value}</b></div>}
function StateBlock({title,value,detail}:{title:string;value:string;detail:string}){return <div className="state-block"><span>{title}</span><b>{value}</b><small>{detail}</small></div>}

function ScenarioLab({config,scenarioId,setScenarioId,lastScenario,run,history}:{config:ArchitectureConfig;scenarioId:string;setScenarioId:(id:string)=>void;lastScenario:ScenarioOutcome|null;run:(id?:string)=>ScenarioOutcome;history:ScenarioOutcome[]}){
 const selected=lastScenario?.id===scenarioId?lastScenario:null;const baseline=history.slice().reverse().find(x=>x.id==='baseline');const compare=selected&&baseline&&selected.id!=='baseline';
 return <><SectionTitle eyebrow="REPRODUCIBLE FAILURE INJECTION · SYNTHETIC ONLY" title="Scenario laboratory" copy="Run 14 deterministic cases against the active architecture. Model-specific cases show Not Applicable unless their design preconditions are selected." actions={<button className="btn secondary" onClick={()=>run('baseline')}><RefreshCw size={14}/> Run baseline</button>}/>
  <div className="scenario-layout"><section className="panel scenario-selector"><div className="eyebrow">SCENARIO CATALOG</div><h2>Select a failure condition</h2><div className="scenario-list">{scenarioCatalog.map(s=><button key={s.id} className={`scenario-choice ${scenarioId===s.id?'active':''}`} onClick={()=>setScenarioId(s.id)}><span><b>{s.name}</b><small>{s.domain}</small></span><ChevronRight size={14}/></button>)}</div></section><section className="panel scenario-detail"><div className="scenario-topline"><div><div className="eyebrow">{scenarioCatalog.find(s=>s.id===scenarioId)?.domain.toUpperCase()}</div><h2>{scenarioCatalog.find(s=>s.id===scenarioId)?.name}</h2></div><button className="btn primary" onClick={()=>run()}><Play size={14}/> Execute scenario</button></div><div className="scenario-conditions"><div><span>Initial conditions</span><p>{scenarioCatalog.find(s=>s.id===scenarioId)?.initial}</p></div><div><span>Injected event</span><p>{scenarioCatalog.find(s=>s.id===scenarioId)?.injection}</p></div><div><span>Expected behavior</span><p>{scenarioCatalog.find(s=>s.id===scenarioId)?.expected}</p></div></div>
   {selected?<><div className={`scenario-result ${selected.status.toLowerCase()}`}><div><span>Observed local result</span><b>{selected.status}</b></div><StatusPill status={selected.status}/></div><div className="scenario-state-grid">{[['Asset state',selected.assetState],['Cash state',selected.cashState],['Custody / authorization',selected.custodyStatus],['Settlement status',selected.settlementStatus]].map(([label,value])=><StateBlock key={label} title={label} value={value} detail="Scenario engine state"/>)}</div><div className="scenario-conditions"><div><span>Reconciliation findings</span>{selected.reconciliationFindings.map((x,i)=><p key={i}>{x}</p>)}</div><div><span>Evidence references</span><p>{selected.evidence.join(' · ')}</p></div><div><span>Recovery procedure</span><p>{selected.recovery}</p></div></div>{compare&&<div className="compare-outcome"><b>Comparison with latest baseline</b><p>Baseline: {baseline!.status} · {baseline!.settlementStatus}. Selected case: {selected.status} · {selected.settlementStatus}.</p></div>}</>:<div className="empty-state tall"><Play size={18}/><p>Execute the selected scenario to create a deterministic result against {config.instrument} / {pretty(config.money)} architecture.</p></div>}
   <div className="method-note compact"><CircleAlert size={14}/><span>PASS means the injected condition produced the expected safe response; it is not a production assurance result or live-network observation.</span></div>
  </section></div><section className="panel scenario-history"><div className="panel-head"><div><div className="eyebrow">PERSISTED BROWSER HISTORY · LAST 20 RUNS</div><h2>Scenario comparison history</h2></div></div>{history.length?<div className="table-wrap"><table><thead><tr><th>Scenario</th><th>Domain</th><th>Result</th><th>Settlement state</th><th>Recovery</th></tr></thead><tbody>{history.slice().reverse().map((r,i)=><tr key={`${r.id}-${i}`}><td>{r.name}</td><td>{r.domain}</td><td><StatusPill status={r.status}/></td><td>{r.settlementStatus}</td><td>{r.recovery}</td></tr>)}</tbody></table></div>:<p className="empty-state">No scenario outcomes stored yet.</p>}</section></>;
}

function ComparePack({workspaces,left,right,setLeft,setRight,differences,pack,onJson,onMarkdown,onCsv}:{workspaces:Workspace[];left:string;right:string;setLeft:(id:string)=>void;setRight:(id:string)=>void;differences:ReturnType<typeof compareArchitectures>;pack:ReturnType<typeof generateDecisionPack>;onJson:()=>void;onMarkdown:()=>void;onCsv:()=>void}){
 return <><SectionTitle eyebrow="ARCHITECTURE DECISION OUTPUT" title="Compare designs and generate a pack" copy="Exports are generated from the active workspace and its live validation results. Comparison reports changed configuration fields and their design trade-offs." actions={<><button className="btn secondary" onClick={onJson}><FileJson size={14}/> JSON pack</button><button className="btn secondary" onClick={onMarkdown}><FileText size={14}/> Markdown pack</button><button className="btn secondary" onClick={onCsv}><Download size={14}/> Matrix CSV</button></>}/>
  <Panel title="Compare saved architecture workspaces" copy="Duplicate a workspace in Architecture Designer, then select two saved designs."><div className="compare-selectors">{[['Design A',left,setLeft],['Design B',right,setRight]].map(([label,value,setter])=><label key={label as string} className="form-field"><span>{label as string}</span><select value={value as string} onChange={e=>(setter as (id:string)=>void)(e.target.value)}><option value="">Select a saved workspace</option>{workspaces.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select></label>)}</div>{left&&right?differences.length?<div className="table-wrap"><table><thead><tr><th>Domain</th><th>Configuration field</th><th>Design A</th><th>Design B</th><th>Trade-off to assess</th></tr></thead><tbody>{differences.map((d,i)=><tr key={`${d.field}-${i}`}><td>{d.domain}</td><td><b>{d.field}</b></td><td>{d.left}</td><td>{d.right}</td><td>{d.tradeoff}</td></tr>)}</tbody></table></div>:<div className="empty-state">The selected configurations are identical.</div>:<div className="empty-state">Choose two workspaces to compare their actual configuration.</div>}</Panel>
  <Panel title="Generated architecture decision pack" copy="The export contains assumptions, systems of record, custody, settlement, findings, risks, research and unresolved legal questions."><div className="pack-summary"><div><span>Pack schema</span><b>Version 1</b></div><div><span>Workspace</span><b>{pack.workspace.name}</b></div><div><span>Validation findings</span><b>{pack.validation.findings.length}</b></div><div><span>Open items</span><b>{pack.outstandingDecisions.length}</b></div></div><p className="pack-preview">{pack.executiveSummary}</p><pre className="pack-json-preview">{JSON.stringify({selectedSystems:pack.selectedSystems,validation:pack.validation.summary,risks:pack.risksAndControls.length},null,2)}</pre></Panel>
 </>;
}

function ResearchPage({query,setQuery,category,setCategory,results}:{query:string;setQuery:(v:string)=>void;category:string;setCategory:(v:string)=>void;results:typeof sources}){
 const categories=['All',...Array.from(new Set(sources.map(s=>s.category)))];return <><SectionTitle eyebrow="TRACEABLE SOURCE REGISTER · ACCESSED 20 NOV 2026" title="Research and sources" copy="Primary legislation, central-bank and market-infrastructure material, and official technology documentation. Source dates are shown only where verified; caveats distinguish announcement from capability."/>
  <div className="research-toolbar"><label className="searchbox"><Search size={15}/><input aria-label="Search research sources" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search source, topic, organization or claim"/></label><select aria-label="Filter source category" value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select><span>{results.length} of {sources.length} sources</span></div>
  <div className="source-list">{results.map(s=><article className="panel source-card" key={s.id}><div className="source-heading"><div><code>{s.id}</code><span className="source-category">{s.category}</span><h2>{s.title}</h2><small>{s.organization} · Publication: {s.publicationDate||'not stated'} · Effective: {s.effectiveDate||'not applicable / not stated'} · Last updated: {s.lastUpdated||'not stated'} · Accessed {s.accessed}</small></div><a className="btn secondary" href={s.url} target="_blank" rel="noreferrer">Open primary source <ArrowUpRight size={13}/></a></div><p>{s.summary}</p><div className="source-claims"><div><b>Claims supported</b><ul>{s.claims.map(x=><li key={x}>{x}</li>)}</ul></div><div><b>Limitations and interpretation</b><p>{s.limitations}</p></div></div><div className="source-topics">{s.subjects.map(topic=><span key={topic}>{topic}</span>)}</div></article>)}{!results.length&&<p className="empty-state">No source records match those filters.</p>}</div>
 </>;
}

function MoneyPage({config,update}:{config:ArchitectureConfig;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void}){
 return <><SectionTitle eyebrow="DIGITAL MONEY DESIGN" title="Select the cash claim and its books deliberately" copy="Deposit mirror and omnibus models change authority, backing, entitlement, liquidity and reconciliation duties. Other cash assets require scheme-specific rules." actions={<button className="btn secondary" onClick={()=>update('money','deposit')}>Use deposits in active design</button>}/>
  <div className="cards-grid">{[
   ['Tokenised commercial bank deposit','A liability of a commercial bank represented on a programmable ledger. Confirm account and customer claim structure, redemption, availability and bank-book synchronization.'],
   ['Deposit mirror','Core banking remains authoritative for the underlying customer deposit. Token cash is a controlled representation. Available account balance and token balance must be checked independently; mismatches block closeout.'],
   ['Omnibus deposit','A pooled bank account backs token positions. The pool asset and the investor entitlement subledger are separate records. Define account ownership, insolvency treatment, reserve coverage, redemption and reconciliation.'],
   ['Wholesale CBDC / central bank money','A central bank liability available to eligible participants under the specific scheme. Access, operating windows, liquidity and legal settlement depend on scheme design.'],
   ['Regulated stablecoin','An issuer liability under its regulatory and reserve framework. Assess redemption, reserve asset, issuer, custody and settlement exposures. Do not equate it to a commercial bank deposit.'],
   ['Existing payment infrastructure','Cash stays in conventional bank/payment systems while a tokenised asset transfer is coordinated. Model timing gaps, payment status, irrevocability, liquidity, returns and recovery.']
  ].map(([title,body])=><article className="panel research-topic" key={title}><div className="eyebrow">CASH MODEL</div><h2>{title}</h2><p>{body}</p></article>)}</div>
  <Panel title="Current workspace controls" copy="Changing these values updates validation, lifecycle behavior and exported decision packs."><div className="form-grid"><Field label="Cash model" value={config.money} options={['deposit','cbdc','stablecoin','existing-rails']} onChange={v=>update('money',v as ArchitectureConfig['money'])}/>{config.money==='deposit'&&<Field label="Deposit model" value={config.depositModel} options={['mirror','omnibus']} onChange={v=>update('depositModel',v as ArchitectureConfig['depositModel'])}/>}<Field label="Liquidity owner" value={config.liquidityOwner} onChange={v=>update('liquidityOwner',v)}/><Field label="Redemption owner" value={config.redemptionOwner} onChange={v=>update('redemptionOwner',v)}/></div><Toggle label="Cash and token records reconcile" checked={config.moneyReconciliation} onChange={v=>update('moneyReconciliation',v)}/></Panel>
 </>;
}
function DltPage({config,update}:{config:ArchitectureConfig;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void}){
 const profiles=[['Hyperledger Besu','Ethereum client; EVM execution and permissioning options. Privacy and governance depend on deployment and transaction design.','Permissioned network option'],['Hyperledger Fabric','Permissioned membership, channels, endorsement and private-data patterns. Operations and cross-channel visibility require explicit design.','Organization-scoped state'],['Canton','Participant and party-scoped contract visibility with synchronization across domains. Participant/synchronizer governance and operating dependencies require diligence.','Scoped visibility / synchronization'],['Ethereum','Public network defaults provide broad transaction visibility; private business data requires a separate approach. External fees and public validator dependencies apply.','Public network'],['Quorum','Enterprise Ethereum lineage. Assess maintenance, support, privacy mechanisms and compatibility for the exact selected distribution.','Deployment dependent'],['Stellar','Public network with asset and payment services. Evaluate issuer controls, privacy and custody assumptions.','Public network'],['Avalanche','Deployment options vary by selected network. Evaluate validator governance, bridge/network dependency and the target operating topology.','Network profile dependent'],['Hedera','Public network and token/consensus services with its governance model and service dependencies.','Governing Council model']];
 return <><SectionTitle eyebrow="DLT PLATFORM RESEARCH · QUALITATIVE ONLY" title="Compare ledger profiles against institutional boundaries" copy="No unsupported throughput rankings. Use a version-specific technical and operational evaluation before choosing a platform." actions={<button className="btn secondary" onClick={()=>update('dlt','Canton')}>Set active profile: Canton</button>}/><Panel title="Profile selection"><Field label="Active architecture profile" value={config.dlt} options={profiles.map(p=>p[0])} onChange={v=>update('dlt',v)}/><Field label="Network topology" value={config.topology} options={['single-ledger','multiple-ledgers','shared-coordination','existing-systems']} onChange={v=>update('topology',v as ArchitectureConfig['topology'])}/></Panel><div className="table-wrap research-matrix"><table><thead><tr><th>Platform</th><th>Visibility / privacy</th><th>Institutional diligence</th><th>Profile</th></tr></thead><tbody>{profiles.map(([name,body,profile])=><tr key={name} className={config.dlt===name?'selected-row':''}><td><b>{name}</b></td><td>{body}</td><td>Identity and participant governance; finality rule; upgrade controls; operational resilience; integration and exit strategy.</td><td>{profile}</td></tr>)}</tbody></table></div><div className="method-note"><CircleAlert size={15}/><span>Technology profiles summarize architectural considerations; version-specific features, performance and support status were not independently certified by this workbench.</span></div></>;
}
function CustodyPage({config,update}:{config:ArchitectureConfig;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void}){
  return <><SectionTitle eyebrow="INSTITUTIONAL CUSTODY OPERATING MODEL" title="Signing authority, segregation and recoverability" copy="Custody is modeled as an institutional operating control, not only a cryptographic threshold. The lifecycle engine blocks settlement when selected custody controls are unavailable."/><div className="cards-grid">{[['Wallet hierarchy','Separate client, treasury and operational wallets; specify ownership, segregation and reconciliation duties.'],['HSM service','The synthetic engine evaluates HSM service availability and authorization policy. It performs no hardware signing.'],['MPC threshold','The synthetic engine compares available signer participants to the configured threshold. It does not implement MPC cryptography.'],['Maker-checker','Represent initiator and independent approval roles; apply delegated authority and transaction limits.'],['Key recovery','Define pause, revocation, backup, key rotation and recovery authority; require tested continuity procedures.'],['Incident operations','Preserve observations, block unsafe retries, assign incident command and reconcile before resumption.']].map(([title,body])=><article className="panel research-topic" key={title}><div className="eyebrow">CUSTODY CONTROL</div><h2>{title}</h2><p>{body}</p></article>)}</div><Panel title="Active custody configuration"><div className="form-grid"><Field label="Custody pattern" value={config.custody} options={['hsm','mpc','hybrid','third-party']} onChange={v=>update('custody',v as ArchitectureConfig['custody'])}/><Field label="Available MPC signers" value={config.mpcAvailableSigners} onChange={v=>update('mpcAvailableSigners',Number(v)||0)}/><Field label="MPC threshold" value={config.mpcThreshold} onChange={v=>update('mpcThreshold',Number(v)||0)}/></div><div className="toggle-grid"><Toggle label="HSM service available" checked={config.hsmAvailable} onChange={v=>update('hsmAvailable',v)}/><Toggle label="Custody policy available" checked={config.custodyPolicy} onChange={v=>update('custodyPolicy',v)}/><Toggle label="Maker-checker control" checked={config.makerChecker} onChange={v=>update('makerChecker',v)}/><Toggle label="Recovery procedure defined" checked={config.keyRecovery} onChange={v=>update('keyRecovery',v)}/></div></Panel></>;
}
function IntegrationPage({config,update}:{config:ArchitectureConfig;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void}){
 const rows=[['Core banking','Deposit account balance and authority','Conceptual adapter · never connected'],['Payment / treasury','Funding, payment instructions and status','Conceptual adapter · never connected'],['Transfer agency','Investor register, eligibility and corporate actions','Conceptual adapter · never connected'],['Trading / OMS','Matched trade capture and canonical references','Conceptual adapter · never connected'],['Custodian','Wallet position, authorization and custody status','Simulated policy boundary'],['KYC / eligibility','Investor category and transfer restrictions','Local configuration only'],['Accounting / reporting','Book positions, cash records and reconciliations','System boundary only'],['DLT network','Token supply, transfer state and technical finality','No network client or transaction']];
 return <><SectionTitle eyebrow="ENTERPRISE INTEGRATION ARCHITECTURE" title="Adapters preserve identity and business status" copy="No external integration is connected. These interface responsibilities are modeled as boundaries for an implementation design."/><div className="table-wrap"><table><thead><tr><th>System</th><th>Data and authority</th><th>Implementation status</th></tr></thead><tbody>{rows.map(r=><tr key={r[0]}><td><b>{r[0]}</b></td><td>{r[1]}</td><td>{r[2]}</td></tr>)}</tbody></table></div><div className="cards-grid two">{[['API and event contract','Use stable business identifiers and idempotency keys. Preserve source record, party, amount, instruction and event time. Define duplicate, replay, delayed and out-of-order behavior.'],['ISO 20022 conceptual mapping','Map applicable business concepts and status to the chosen payment/settlement adapters. A conceptual mapping does not implement or certify a message interface.'],['Reconciliation and breaks','Compare legal register, token positions, bank account, token cash and settlement coordinator state independently. Preserve discrepancies until resolved by their owner.'],['Event and evidence model','Capture command, source observation, authorization reference, external status and reconciliation result. Local sandbox events are synthetic and unsigned.']].map(([title,body])=><article className="panel research-topic" key={title}><h2>{title}</h2><p>{body}</p></article>)}</div><Panel title="Integration controls"><div className="toggle-grid"><Toggle label="Canonical transaction identifiers" checked={config.canonicalIds} onChange={v=>update('canonicalIds',v)}/><Toggle label="Idempotency and replay protection" checked={config.idempotency} onChange={v=>update('idempotency',v)}/><Toggle label="ISO 20022 conceptual mapping" checked={config.iso20022Mapping} onChange={v=>update('iso20022Mapping',v)}/><Toggle label="Independent observer sources" checked={config.independentObservers} onChange={v=>update('independentObservers',v)}/></div></Panel></>;
}
function RegulationPage({query,setQuery,category,setCategory,results,jurisdiction,update}:{query:string;setQuery:(v:string)=>void;category:string;setCategory:(v:string)=>void;results:typeof sources;jurisdiction:string;update:(k:keyof ArchitectureConfig,v:ArchitectureConfig[keyof ArchitectureConfig])=>void}){
 return <><SectionTitle eyebrow="REGULATORY AND STANDARDS LANDSCAPE" title="Map legal questions to authoritative sources" copy="This library identifies primary texts and architecture topics; it does not decide legal classification, applicability or compliance."/><Panel title="Jurisdiction context" copy="Set the design jurisdiction, then search the source register for relevant primary texts."><Field label="Workspace jurisdiction" value={jurisdiction} options={['European Union','United Kingdom','United States','Other']} onChange={v=>update('jurisdiction',v)}/><p className="regulation-note">EU references in the current source register include DORA, MiCA and the DLT Pilot Regime. Applicability depends on instrument classification, entity, activity and jurisdiction. Review current consolidated law and local implementation.</p></Panel><ResearchPage query={query} setQuery={setQuery} category={category==='All'?'Legislation':category} setCategory={setCategory} results={results.filter(s=>s.category==='Legislation'||s.category==='Regulator / central bank')}/></>;
}
function UseCaseDecision(){
 const saas=useSaaS();
 const [assessmentTitle,setAssessmentTitle]=useState('Tokenisation use-case assessment');
 const [selectedAssessmentId,setSelectedAssessmentId]=useState<string|null>(null);
 const [cloudMessage,setCloudMessage]=useState('');
 const [inputs,setInputs]=useState<UseCaseInputs>(()=>{if(saas.enabled)return defaultUseCaseInputs;try{const raw=localStorage.getItem('ita-use-case-decision-v1');if(!raw)return defaultUseCaseInputs;const saved=JSON.parse(raw) as Partial<UseCaseInputs>;return {...defaultUseCaseInputs,...saved,readiness:{...defaultUseCaseInputs.readiness,...saved.readiness}};}catch{return defaultUseCaseInputs;}});
 const decision=useMemo(()=>evaluateUseCase(inputs),[inputs]);
 useEffect(()=>{if(saas.enabled)return;try{localStorage.setItem('ita-use-case-decision-v1',JSON.stringify(inputs));}catch{console.warn('Decision workspace could not be saved in browser storage.');}},[inputs,saas.enabled]);
 const updateReadiness=(key:keyof Readiness,value:boolean)=>setInputs(current=>({...current,readiness:{...current.readiness,[key]:value}}));
 const toggleFriction=(key:Friction)=>setInputs(current=>({...current,frictions:current.frictions.includes(key)?current.frictions.filter(x=>x!==key):[...current.frictions,key]}));
 const toggleMechanism=(key:TokenisationMechanism)=>setInputs(current=>({...current,tokenisationMechanisms:current.tokenisationMechanisms.includes(key)?current.tokenisationMechanisms.filter(x=>x!==key):[...current.tokenisationMechanisms,key]}));
 const canWrite=Boolean(saas.organization&&['owner','admin','editor'].includes(saas.organization.role));
 const saveToInstitution=async()=>{try{setCloudMessage('Saving…');const result=await saas.saveAssessment({id:selectedAssessmentId,title:assessmentTitle,useCase:inputs.useCase,inputs:JSON.parse(JSON.stringify(inputs)) as Record<string,unknown>,decision:JSON.parse(JSON.stringify(decision)) as Record<string,unknown>});setSelectedAssessmentId(result.id);setCloudMessage('Saved · version '+result.version+' · '+new Date().toLocaleTimeString());}catch(e){setCloudMessage(e instanceof Error?e.message:'Could not save assessment.');}};
 const openCloudAssessment=(item:(typeof saas.assessments)[number])=>{const saved=item.inputs as unknown as Partial<UseCaseInputs>;setInputs({...defaultUseCaseInputs,...saved,readiness:{...defaultUseCaseInputs.readiness,...saved.readiness}});setAssessmentTitle(item.title);setSelectedAssessmentId(item.id);setCloudMessage('Loaded version '+item.version);};
 const exportJson=()=>download('tokenisation-use-case-decision.json',JSON.stringify({schemaVersion:'1.0',generatedAt:new Date().toISOString(),inputs,decision},null,2),'application/json');
 const exportMemo=()=>download('tokenisation-use-case-decision.md',[
  '# Tokenisation use-case decision', '', '**Verdict:** '+decision.verdict, '', decision.rationale, '', '## Workflow baseline', '- Use case: '+pretty(inputs.useCase), '- Events per year: '+inputs.annualEvents, '- Participating parties: '+inputs.participants, '- Operational frictions: '+(inputs.frictions.join(', ')||'None selected'), '- Evidence: '+(inputs.baselineEvidence||'Not supplied'), '- Tokenisation mechanisms: '+(inputs.tokenisationMechanisms.join(', ')||'None selected'), '- Why simpler alternatives are insufficient: '+(inputs.existingSystemGap||'Not supplied'), '', '## Decision gates', ...decision.gates.map(g=>'- '+g.status+': '+g.label+' — '+(g.status==='OPEN'?g.consequence:'Evidence marked ready by the user')), '', '## Pilot boundary', ...decision.pilotScope.map(x=>'- '+x), '', '## Architecture principles', ...decision.architecture.map(x=>'- '+x), '', '## Success measures', ...decision.successMeasures.map(x=>'- '+x), '', '## Next actions', ...decision.nextActions.map(x=>'- '+x), '', '> User-entered readiness is an assertion, not independently verified evidence. This decision aid is not legal, regulatory or investment advice and does not approve production deployment.'
 ].join('\n'),'text/markdown');
 return <><SectionTitle eyebrow="BUSINESS CASE BEFORE TECHNOLOGY" title="Should this workflow be tokenised?" copy="Evaluate a real financial workflow before selecting a ledger. The result is a transparent decision with open gates, a bounded pilot scope and measurable outcomes — not a readiness score." actions={<>{saas.enabled&&canWrite&&<button className="btn primary" onClick={saveToInstitution}><ShieldCheck size={14}/> Save to institution</button>}<button className="btn secondary" onClick={exportJson}><FileJson size={14}/> Export decision JSON</button><button className="btn secondary" onClick={exportMemo}><Download size={14}/> Export decision memo</button></>}/>
  <div className="usecase-intro"><b>Start with the operational problem.</b><span>Tokenisation is only justified if it improves a measurable workflow and the legal, cash and operating model can support it.</span></div>
  {saas.enabled&&<><Panel title="Institutional assessment record" copy="Cloud records are scoped to the selected organisation and versioned in the database."><div className="form-grid"><Field label="Assessment title" value={assessmentTitle} onChange={setAssessmentTitle}/><div className="form-field"><span>Record access</span><strong>{saas.organization?.role||'No role'}</strong><small>{canWrite?'You can create and update assessments.':'Read-only access. Ask an organisation administrator for editor access.'}</small></div></div>{cloudMessage&&<p className="regulation-note">{cloudMessage}</p>}<div className="gate-list">{saas.assessments.map(item=><article key={item.id}><span className="gate-status ready">V{item.version}</span><div><b>{item.title}</b><p>{pretty(item.use_case)} · Updated {new Date(item.updated_at).toLocaleString()}</p><button className="saas-text-button" onClick={()=>openCloudAssessment(item)}>Open assessment</button></div></article>)}{saas.assessments.length===0&&<p>No cloud assessments yet. Save the current assessment to create the first record.</p>}</div></Panel><Panel title="Organisation audit trail" copy="Database-generated assessment events for the selected organisation. The current view shows the latest 100 events."><div className="gate-list">{saas.auditEvents.map(event=><article key={event.id}><span className="gate-status ready">{event.action.replace('assessment.','').toUpperCase()}</span><div><b>{String(event.payload.title||event.entity_type+' '+event.entity_id.slice(0,8))}</b><p>{new Date(event.created_at).toLocaleString()} · {event.actor_id||'System event'} · {String(event.payload.version?'v'+event.payload.version:'')}</p></div></article>)}{saas.auditEvents.length===0&&<p>No audit events yet.</p>}</div></Panel></>}
  <div className="usecase-grid"><div className="usecase-inputs">
   <Panel title="1 · Define the workflow" copy="Describe the business process, not the technology you hope to use."><div className="form-grid"><label className="form-field"><span>Financial use case</span><select value={inputs.useCase} onChange={e=>setInputs(c=>({...c,useCase:e.target.value as UseCaseInputs['useCase']}))}><option value="tokenised-bond">Tokenised bond issuance</option><option value="fund-units">Fund units and transfer agency</option><option value="private-credit">Private credit participation</option><option value="collateral">Collateral allocation and pledge preparation</option></select></label><Field label="Workflow events per year" value={inputs.annualEvents} onChange={v=>setInputs(c=>({...c,annualEvents:Math.max(0,Math.floor(Number(v)||0))}))}/><Field label="Participating organisations / parties" value={inputs.participants} onChange={v=>setInputs(c=>({...c,participants:Math.max(0,Math.floor(Number(v)||0))}))}/></div><div className="form-field"><span>What is currently painful or inefficient?</span><div className="choice-list">{frictionOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={inputs.frictions.includes(key)} onChange={()=>toggleFriction(key)}/><span>{label}</span></label>)}</div></div><label className="form-field"><span>Baseline evidence · current cost, time, failure or exception rate</span><textarea rows={4} value={inputs.baselineEvidence} onChange={e=>setInputs(c=>({...c,baselineEvidence:e.target.value}))} placeholder="Example: monthly reconciliation takes 2 days, involves 3 counterparties and produces 12 unresolved breaks..."/><small>Use observed or attributable data. A hypothesis is not a baseline.</small></label><div className="form-field"><span>What requires tokenisation rather than a conventional database or API?</span><div className="choice-list">{mechanismOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={inputs.tokenisationMechanisms.includes(key)} onChange={()=>toggleMechanism(key)}/><span>{label}</span></label>)}</div></div><label className="form-field"><span>Why are simpler alternatives insufficient?</span><textarea rows={3} value={inputs.existingSystemGap} onChange={e=>setInputs(c=>({...c,existingSystemGap:e.target.value}))} placeholder="Explain which cross-party coordination, shared-state or rights-control requirement cannot be met adequately by the current database/API workflow..."/><small>Do not assume a distributed ledger is necessary merely because several parties are involved.</small></label></Panel>
   <Panel title="2 · Confirm minimum prerequisites" copy="Mark a gate ready only when you have identified the relevant owner, rule or evidence. These are user assertions, not verified facts."><div className="readiness-list">{([['legalRegisterKnown','Authoritative legal register and ownership record identified'],['transferRulesDefined','Transfer restrictions, eligibility and consent rules documented'],['settlementRouteKnown','Cash instrument, settlement operator and recovery route identified'],['accountableOwner','Accountable workflow and exception owner assigned'],['pilotCounterpartyIdentified','At least one real pilot counterparty identified'],['usableDataAvailable','Representative workflow data can be accessed']] as [keyof Readiness,string][]).map(([key,label])=><Toggle key={key} label={label} checked={inputs.readiness[key]} onChange={v=>updateReadiness(key,v)}/>)}</div></Panel>
  </div><aside className="usecase-output"><div className={'decision-verdict '+decision.verdict.toLowerCase().replace(/ /g,'-')}><span className="eyebrow">CURRENT DECISION</span><strong>{decision.verdict}</strong><p>{decision.rationale}</p></div>
   <Panel title="Decision gates" copy="Every gate is visible. Open gates explain what prevents a pilot recommendation."><div className="gate-list">{decision.gates.map(g=><article key={g.id}><span className={'gate-status '+g.status.toLowerCase()}>{g.status}</span><div><b>{g.label}</b>{g.status==='OPEN'&&<p>{g.consequence}</p>}</div></article>)}</div></Panel>
   <Panel title="Recommended pilot boundary" copy={'Workflow profile: '+inputs.annualEvents+' events/year · '+inputs.participants+' parties.'}><ul className="decision-bullets">{decision.pilotScope.map(x=><li key={x}>{x}</li>)}</ul></Panel>
   <Panel title="Architecture principles" copy="Platform-neutral defaults; do not select a DLT stack before proving the workflow."><ul className="decision-bullets">{decision.architecture.map(x=><li key={x}>{x}</li>)}</ul></Panel>
   <Panel title="Measure success against" copy="Choose a small number of baseline metrics and compare like-for-like cases."><ul className="decision-bullets">{decision.successMeasures.map(x=><li key={x}>{x}</li>)}</ul></Panel>
   <Panel title="Next actions"><ol className="decision-bullets">{decision.nextActions.map(x=><li key={x}>{x}</li>)}</ol></Panel>
   <div className="method-note"><ShieldCheck size={15}/><span>A PILOT CANDIDATE is not a production approval. The tool does not verify legal rights, data quality, counterparty commitment or economic claims. It makes missing assumptions explicit.</span></div>
  </aside></div></>;
}

function AboutPage(){return <><SectionTitle eyebrow="PROJECT IDENTITY AND SCOPE" title="An architecture and engineering workbench" copy="Tokenisation crosses legal rights, financial assets, money, custody, settlement, liquidity, banking infrastructure and institutional governance."/><div className="about-grid"><section className="panel about-main"><h2>What this workbench does</h2><p>It evaluates tokenisation use cases against explicit business, legal, settlement and operating gates; configures an institutional asset and cash architecture; executes synthetic financial lifecycle commands; injects operational failures; compares saved designs; and exports decision packs.</p><h2>Who it is for</h2><p>Bank CTOs, enterprise and solution architects, digital-asset and capital-markets technology teams, custody and settlement specialists, financial market infrastructure operators and asset managers.</p><h2>How it works</h2><p>React and TypeScript present a versioned workspace saved in browser storage. Pure domain functions validate architecture choices, maintain separate register, token, bank-cash and token-cash records, enforce lifecycle invariants, produce reproducible scenario results and generate JSON, Markdown and CSV exports.</p><h2>Limitations</h2><ul><li>Implemented: use-case decision gates, local configuration, validation, lifecycle simulation, 14 scenario specifications, comparison and pack exports.</li><li>Synthetic sandbox: all balances, actors, statuses, evidence IDs and network conditions.</li><li>Conceptual: banking/DLT/custody adapters, ISO 20022 integration and legal-system mappings.</li><li>Not implemented: login, backend persistence, external APIs, production cryptography, live network or payments.</li><li>Legal and regulatory determinations remain with qualified institutional advisers and authorities.</li></ul></section><aside className="panel author-panel"><div className="author-monogram">VG</div><div className="eyebrow">AUTHOR</div><h2>Vishnu Govind</h2><p>Founder, Universal Ventures</p><p>Institutional financial infrastructure architecture, tokenised finance, capital markets and distributed financial systems.</p><div className="author-links"><a href="https://github.com/vishnugovind10" target="_blank" rel="noreferrer">GitHub <ArrowUpRight size={13}/></a><a href="https://www.linkedin.com/in/vishnu-govind" target="_blank" rel="noreferrer">LinkedIn <ArrowUpRight size={13}/></a><a href="https://universal-ventures.vercel.app/thesis" target="_blank" rel="noreferrer">Universal Ventures <ArrowUpRight size={13}/></a></div></aside></div><div className="method-note"><ShieldCheck size={15}/><span>This project is independent and synthetic. It makes no claims of client deployment, partnership, endorsement, audit, regulatory approval or production readiness.</span></div></>;
}
function download(filename:string,content:string,mime:string){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
function fileName(value:string){return value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'architecture';}
